// Procedural SFX. Every sound is synthesized into a Float32Array by pure DSP
// (no AudioContext needed for generation), so the playtest harness can verify
// peak/RMS/duration of every effect headlessly.

const SR = 44100;

function buffer(seconds) {
  return new Float32Array(Math.floor(SR * seconds));
}

// Cheap deterministic noise
function makeNoise(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return (s / 4294967296) * 2 - 1;
  };
}

// One-pole lowpass over an existing buffer, in place
function lowpass(buf, cutoffHz) {
  const a = 1 - Math.exp(-2 * Math.PI * cutoffHz / SR);
  let y = 0;
  for (let i = 0; i < buf.length; i++) {
    y += a * (buf[i] - y);
    buf[i] = y;
  }
  return buf;
}

function highpass(buf, cutoffHz) {
  const a = 1 - Math.exp(-2 * Math.PI * cutoffHz / SR);
  let lp = 0;
  for (let i = 0; i < buf.length; i++) {
    lp += a * (buf[i] - lp);
    buf[i] = buf[i] - lp;
  }
  return buf;
}

function expEnv(buf, decay) {
  for (let i = 0; i < buf.length; i++) buf[i] *= Math.exp(-i / SR * decay);
  return buf;
}

function addSine(buf, freqStart, freqEnd, amp, decay, offset = 0) {
  let phase = 0;
  const n = buf.length;
  const off = Math.floor(offset * SR);
  for (let i = off; i < n; i++) {
    const t = (i - off) / SR;
    const k = (i - off) / (n - off);
    const f = freqStart + (freqEnd - freqStart) * k;
    phase += 2 * Math.PI * f / SR;
    buf[i] += Math.sin(phase) * amp * Math.exp(-t * decay);
  }
  return buf;
}

function addNoiseBurst(buf, amp, decay, seed, offset = 0, len = 1) {
  const rnd = makeNoise(seed);
  const off = Math.floor(offset * SR);
  const end = Math.min(buf.length, off + Math.floor(len * SR));
  for (let i = off; i < end; i++) {
    const t = (i - off) / SR;
    buf[i] += rnd() * amp * Math.exp(-t * decay);
  }
  return buf;
}

function addClick(buf, amp, offset, seed) {
  const rnd = makeNoise(seed);
  const off = Math.floor(offset * SR);
  const len = Math.floor(0.012 * SR);
  for (let i = 0; i < len && off + i < buf.length; i++) {
    buf[off + i] += rnd() * amp * Math.exp(-i / SR * 600);
  }
  return buf;
}

function normalize(buf, target = 0.85) {
  let peak = 0;
  for (let i = 0; i < buf.length; i++) peak = Math.max(peak, Math.abs(buf[i]));
  if (peak > 0) {
    const g = target / peak;
    for (let i = 0; i < buf.length; i++) buf[i] *= g;
  }
  return buf;
}

// ---------- generators ----------

function genShotRifle() {
  const b = buffer(0.42);
  addNoiseBurst(b, 1.0, 38, 1234);
  lowpass(b, 3800);
  addSine(b, 160, 45, 0.9, 22);
  addClick(b, 0.9, 0, 99);
  return normalize(b);
}

function genShotPistol() {
  const b = buffer(0.3);
  addNoiseBurst(b, 1.0, 55, 4321);
  lowpass(b, 5200);
  addSine(b, 220, 70, 0.7, 35);
  addClick(b, 1.0, 0, 7);
  return normalize(b, 0.8);
}

function genShotSniper() {
  const b = buffer(0.9);
  addNoiseBurst(b, 1.0, 16, 555);
  lowpass(b, 2600);
  addSine(b, 110, 30, 1.1, 9);
  addNoiseBurst(b, 0.25, 6, 777, 0.05, 0.8); // long tail
  addClick(b, 1.0, 0, 31);
  return normalize(b);
}

function genShotShotgun() {
  const b = buffer(0.6);
  addNoiseBurst(b, 1.0, 24, 888);
  lowpass(b, 3000);
  addSine(b, 130, 40, 1.0, 14);
  addClick(b, 0.8, 0, 13);
  return normalize(b);
}

function genShotSMG() {
  const b = buffer(0.22);
  addNoiseBurst(b, 1.0, 70, 2468);
  lowpass(b, 6000);
  addSine(b, 260, 90, 0.55, 50);
  addClick(b, 0.9, 0, 5);
  return normalize(b, 0.75);
}

function genKnife() {
  const b = buffer(0.18);
  addNoiseBurst(b, 0.8, 80, 1357);
  highpass(b, 1800);
  addSine(b, 900, 500, 0.2, 60);
  return normalize(b, 0.5);
}

function genDryFire() {
  const b = buffer(0.1);
  addClick(b, 1.0, 0, 21);
  addClick(b, 0.5, 0.04, 22);
  return normalize(b, 0.5);
}

function genReload() {
  const b = buffer(0.85);
  addClick(b, 0.8, 0.02, 41);
  addNoiseBurst(b, 0.3, 90, 42, 0.05, 0.06);
  addClick(b, 0.7, 0.35, 43);
  addClick(b, 0.9, 0.62, 44);
  addNoiseBurst(b, 0.35, 70, 45, 0.64, 0.08);
  lowpass(b, 4500);
  return normalize(b, 0.6);
}

function genHit() {
  const b = buffer(0.09);
  addSine(b, 2200, 1400, 0.8, 90);
  addClick(b, 0.4, 0, 61);
  return normalize(b, 0.55);
}

function genHeadshot() {
  const b = buffer(0.16);
  addSine(b, 2800, 2100, 0.7, 55);
  addSine(b, 4200, 3500, 0.4, 70, 0.02);
  addClick(b, 0.5, 0, 71);
  return normalize(b, 0.65);
}

function genHurt() {
  const b = buffer(0.25);
  addNoiseBurst(b, 0.9, 40, 911);
  lowpass(b, 900);
  addSine(b, 140, 70, 0.7, 25);
  return normalize(b, 0.7);
}

function genFootstep() {
  const b = buffer(0.12);
  addNoiseBurst(b, 0.8, 90, 313);
  lowpass(b, 700);
  addClick(b, 0.25, 0, 314);
  return normalize(b, 0.32);
}

function genJump() {
  const b = buffer(0.15);
  addNoiseBurst(b, 0.6, 60, 515);
  lowpass(b, 1200);
  return normalize(b, 0.35);
}

function genLand() {
  const b = buffer(0.2);
  addNoiseBurst(b, 0.9, 45, 616);
  lowpass(b, 500);
  addSine(b, 90, 40, 0.6, 30);
  return normalize(b, 0.5);
}

function genBotDeath() {
  const b = buffer(0.55);
  addSine(b, 800, 60, 0.7, 8);
  addNoiseBurst(b, 0.6, 20, 717, 0.05, 0.4);
  lowpass(b, 2200);
  addClick(b, 0.8, 0, 718);
  return normalize(b, 0.75);
}

function genBuy() {
  const b = buffer(0.3);
  addSine(b, 880, 880, 0.5, 20);
  addSine(b, 1320, 1320, 0.45, 18, 0.09);
  return normalize(b, 0.5);
}

function genDeny() {
  const b = buffer(0.25);
  addSine(b, 220, 180, 0.6, 14);
  addSine(b, 165, 140, 0.5, 14, 0.1);
  return normalize(b, 0.5);
}

function genRoundStart() {
  const b = buffer(0.5);
  addSine(b, 660, 660, 0.5, 9);
  addSine(b, 990, 990, 0.5, 9, 0.18);
  return normalize(b, 0.6);
}

function genRoundWin() {
  const b = buffer(1.1);
  addSine(b, 523, 523, 0.5, 7);
  addSine(b, 659, 659, 0.5, 7, 0.16);
  addSine(b, 784, 784, 0.5, 6, 0.32);
  addSine(b, 1046, 1046, 0.6, 4, 0.48);
  return normalize(b, 0.65);
}

function genRoundLose() {
  const b = buffer(1.1);
  addSine(b, 392, 392, 0.5, 6);
  addSine(b, 330, 330, 0.5, 6, 0.22);
  addSine(b, 262, 262, 0.6, 4, 0.44);
  lowpass(b, 1600);
  return normalize(b, 0.6);
}

function genAmbient() {
  const b = buffer(4.0);
  const rnd = makeNoise(31337);
  // wind bed
  for (let i = 0; i < b.length; i++) b[i] = rnd() * 0.5;
  lowpass(b, 220);
  // slow amplitude wobble + hum
  for (let i = 0; i < b.length; i++) {
    const t = i / SR;
    b[i] *= 0.5 + 0.5 * Math.sin(2 * Math.PI * 0.21 * t);
    b[i] += 0.08 * Math.sin(2 * Math.PI * 55 * t) * (0.7 + 0.3 * Math.sin(2 * Math.PI * 0.13 * t));
  }
  // crossfade loop seam
  const fade = Math.floor(0.25 * SR);
  for (let i = 0; i < fade; i++) {
    const k = i / fade;
    b[i] = b[i] * k + b[b.length - fade + i] * (1 - k);
  }
  return normalize(b, 0.3);
}

export const SFX_GENERATORS = {
  shot_rifle: genShotRifle,
  shot_pistol: genShotPistol,
  shot_sniper: genShotSniper,
  shot_shotgun: genShotShotgun,
  shot_smg: genShotSMG,
  knife: genKnife,
  dryfire: genDryFire,
  reload: genReload,
  hit: genHit,
  headshot: genHeadshot,
  hurt: genHurt,
  footstep: genFootstep,
  jump: genJump,
  land: genLand,
  bot_death: genBotDeath,
  buy: genBuy,
  deny: genDeny,
  round_start: genRoundStart,
  round_win: genRoundWin,
  round_lose: genRoundLose,
  ambient: genAmbient,
};

export class AudioEngine {
  constructor(settings) {
    this.settings = settings;
    this.ctx = null;
    this.buffers = {};
    this.raw = {};
    this.ambientNode = null;
    for (const [name, gen] of Object.entries(SFX_GENERATORS)) {
      this.raw[name] = gen();
    }
  }

  // Must be called from a user gesture
  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.connect(this.ctx.destination);
    for (const [name, data] of Object.entries(this.raw)) {
      const buf = this.ctx.createBuffer(1, data.length, SR);
      buf.getChannelData(0).set(data);
      this.buffers[name] = buf;
    }
    this._applyVolumes();
  }

  _applyVolumes() {
    if (this.master) this.master.gain.value = this.settings.get('audio.master') / 100;
  }

  // pan: -1..1, dist: world units (0 = full volume)
  play(name, { pan = 0, dist = 0, vol = 1, category = 'sfx' } = {}) {
    if (!this.ctx || this.ctx.state !== 'running') return;
    const buf = this.buffers[name];
    if (!buf) return;
    this._applyVolumes();
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const gain = this.ctx.createGain();
    const catVol = this.settings.get(`audio.${category}`) / 100;
    const att = dist > 0 ? Math.min(1, 9 / (dist + 3)) : 1;
    gain.gain.value = vol * catVol * att;
    src.connect(gain);
    if (this.ctx.createStereoPanner) {
      const p = this.ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(p);
      p.connect(this.master);
    } else {
      gain.connect(this.master);
    }
    src.start();
  }

  startAmbient() {
    if (!this.ctx || this.ambientNode) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.buffers.ambient;
    src.loop = true;
    const gain = this.ctx.createGain();
    gain.gain.value = this.settings.get('audio.ambient') / 100;
    src.connect(gain);
    gain.connect(this.master);
    src.start();
    this.ambientNode = { src, gain };
  }

  updateAmbient() {
    if (this.ambientNode) {
      this.ambientNode.gain.gain.value = this.settings.get('audio.ambient') / 100;
    }
    this._applyVolumes();
  }

  // Test hook: report stats on every generated sound
  report() {
    const out = {};
    for (const [name, data] of Object.entries(this.raw)) {
      let peak = 0, sum = 0;
      for (let i = 0; i < data.length; i++) {
        const v = Math.abs(data[i]);
        if (v > peak) peak = v;
        sum += data[i] * data[i];
      }
      out[name] = {
        seconds: +(data.length / SR).toFixed(3),
        peak: +peak.toFixed(4),
        rms: +Math.sqrt(sum / data.length).toFixed(4),
      };
    }
    return out;
  }
}
